    h, w = len(grid), len(grid[0])
    # These puzzles use an n-by-n array of n-by-n motifs, separated by one cell.
    n = int(((__import__('math').isqrt(4 * h + 5) - 1) // 2))
    if n * n + n - 1 != h or w != h:
        raise ValueError("unexpected grid dimensions")
    step = n + 1
    out = [row[:] for row in grid]
    tiles = [[None for _ in range(n)] for _ in range(n)]
    for tr in range(n):
        for tc in range(n):
            r0, c0 = tr * step, tc * step
            tiles[tr][tc] = [row[c0:c0+n] for row in grid[r0:r0+n]]

    masked_rows = [r for r in range(n) if all(all(v == 3 for row in tiles[r][c] for v in row) for c in range(n))]
    masked_cols = [c for c in range(n) if all(all(v == 3 for row in tiles[r][c] for v in row) for r in range(n))]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    def is_masked(tr, tc):
        return tr in masked_rows or tc in masked_cols

    # Existing motifs: mark the pixel indexed by that motif's position.
    for tr in range(n):
        for tc in range(n):
            if is_masked(tr, tc):
                continue
            r, c = tr * step + tr, tc * step + tc
            if r < h and c < w and out[r][c] == 2:
                out[r][c] = 8

    # Reconstruct each hidden motif from a visible motif in its row/column,
    # but only when a visible motif marks its own address and the copied motif
    # has a 2 at the hidden motif's address.
    for tr in masked_rows:
        for tc in range(n):
            candidates = [tiles[sr][tc] for sr in range(n) if sr not in masked_rows and not is_masked(sr, tc)
                          and tiles[sr][tc][sr][tc] == 2
                          and tiles[sr][tc][tr][tc] == 2]
            if candidates:
                motif = candidates[0]
                r0, c0 = tr * step, tc * step
                for i in range(n):
                    for j in range(n):
                        out[r0+i][c0+j] = motif[i][j]
                out[r0+tr][c0+tc] = 8
    for tc in masked_cols:
        for tr in range(n):
            candidates = [tiles[tr][sc] for sc in range(n) if sc not in masked_cols and not is_masked(tr, sc)
                          and tiles[tr][sc][tr][sc] == 2
                          and tiles[tr][sc][tr][tc] == 2]
            if candidates:
