def transform(grid):
    h, w = len(grid), len(grid[0])
    if h != w:
        raise ValueError("expected a square tiled grid")
    n = next((k for k in range(1, h + 1) if k * k + k - 1 == h), None)
    if n is None:
        raise ValueError("unexpected grid dimensions")
    step = n + 1

    tiles = []
    masked = set()
    nonempty = []
    for tr in range(n):
        row = []
        for tc in range(n):
            r0, c0 = tr * step, tc * step
            tile = [grid[r0 + i][c0:c0 + n] for i in range(n)]
            row.append(tile)
            vals = [v for line in tile for v in line]
            if vals and all(v == 3 for v in vals):
                masked.add((tr, tc))
            elif any(v == 2 for v in vals):
                nonempty.append(tuple(tuple(line) for line in tile))
        tiles.append(row)
    if not nonempty:
        raise ValueError("no unmasked motif")
    # The repeated mini-picture is also the macro occupancy map: a 2 at
    # (tile-row, tile-column) means that tile belongs in that macro position.
    template = [list(line) for line in Counter(nonempty).most_common(1)[0][0]]

    out = [row[:] for row in grid]
    # Clear the occlusion, preserving all already-visible tiles.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    for tr in range(n):
        for tc in range(n):
            r0, c0 = tr * step, tc * step
            if (tr, tc) in masked:
                if template[tr][tc] == 2:
                    for i in range(n):
                        for j in range(n):
                            out[r0 + i][c0 + j] = template[i][j]
                else:
                    for i in range(n):
                        for j in range(n):
                            out[r0 + i][c0 + j] = 0
            tile = [out[r0 + i][c0:c0 + n] for i in range(n)]
            # Mark the local coordinate corresponding to this tile's address.
            if tile[tr][tc] == 2:
                out[r0 + tr][c0 + tc] = 8
    return out
